// Hilfsfunktionen für Dekomprimierung
function getDriverConstructors(driverId) {
    const data = D_CON[driverId];
    if (!data) return {};
    const result = {};
    for (const entry of data.split(',')) {
        const [yearOffset, cIdx] = entry.split('.').map(Number);
        const year = yearOffset + 1950;
        if (!result[year]) result[year] = [];
        result[year].push(C_IDX[cIdx]);
    }
    return result;
}

function getConstructorPosition(constructorId, year) {
    const idx = C_IDX.indexOf(constructorId);
    if (idx === -1) return null;
    const posData = C_POS[idx];
    if (!posData) return null;
    for (const entry of posData.split(',')) {
        const [y, pos] = entry.split(':').map(Number);
        if (y === year) return pos;
    }
    return null;
}

function getConstructorIdByName(name) {
    // Normalisiere Namen für Lookup
    const normalized = name.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');
    if (C_IDX.includes(normalized)) return normalized;
    // Fallback: Suche ähnliche
    return C_IDX.find(c => c.includes(normalized) || normalized.includes(c)) || null;
}

