// Prüft ob ein Konstrukteur ein Indy-500-only Konstrukteur ist
function isIndyOnlyConstructor(constructorId) {
    if (!constructorId) return false;
    const normalized = constructorId.toLowerCase().replace(/[^a-z0-9]/g, '-');
    return INDY_500_ONLY_CONSTRUCTORS.includes(normalized);
}

// Prüft ob ein Fahrer ein Indy-500-only Fahrer ist
function isIndyOnlyDriver(driverId) {
    if (!driverId) return false;
    const normalized = driverId.toLowerCase().replace(/[^a-z0-9]/g, '-');
    return INDY_500_ONLY_DRIVERS.includes(normalized);
}

