// Funktion: Lade historische StATS für ein Startjahr
function getHistoricalStATS(startYear) {
    const result = {
        drivers: {},
        teams: {},
        champions: [],
        totalRaces: 0
    };
    
    for (const [driverId, data] of Object.entries(HIST_DRIVERS)) {
        const [wins, podiums, poles, points, races, championships, firstYear, lastYear] = data;
        // v0.8.2.4: Indy/F1 Flag
        const driverIsIndyOnly = isIndyOnlyDriver(driverId);
        // v0.9.14.43: Indy-only NICHT mehr ausgenommen — seit dem Indy/F1-Crossover
        // fahren sie im Sim mit (Indy 500) und können sterben. Design-Regel:
        // Sämtliche Statistik kommt aus der Sim-Zeitlinie; nur Saisons VOR dem
        // Startjahr sind gemeinsame Vorgeschichte, Zukunft wird nie geseedet.
        // (Vorher: komplette reale Karriere inkl. Zukunft → "9 Starts" im Jahr 1
        // + Doppelzählung mit Sim-Indy-Starts.)
        if (firstYear >= startYear) continue;

        // Berechne StATS bis Vorjahr aus echten Saison-Daten
        const seasons = HIST_SEASONS[driverId] || [];
        const relevantSeasons = seasons.filter(s => s[0] < startYear);

        if (relevantSeasons.length === 0) continue;

        const calcWins = relevantSeasons.reduce((sum, s) => sum + s[2], 0);
        const calcPodiums = relevantSeasons.reduce((sum, s) => sum + s[3], 0);
        const calcPoints = relevantSeasons.reduce((sum, s) => sum + s[4], 0);
        const calcChamps = relevantSeasons.filter(s => s[1] === '1').length;
        const calcFirst = Math.min(...relevantSeasons.map(s => s[0]));
        const calcLast = Math.max(...relevantSeasons.map(s => s[0]));

        result.drivers[driverId] = {
            name: HIST_NAMES[driverId] || driverId,
            wins: calcWins,
            podiums: calcPodiums,
            poles: Math.round(poles * relevantSeasons.length / seasons.length),
            points: Math.round(calcPoints * 10) / 10,
            races: Math.round(races * relevantSeasons.length / seasons.length),
            championships: calcChamps,
            firstYear: calcFirst,
            lastYear: calcLast,
            isLegend: lastYear < startYear,
            seasons: relevantSeasons,
            hasIndy: driverIsIndyOnly,
            hasF1: !driverIsIndyOnly
        };
    }
    
    for (const [teamName, data] of Object.entries(HIST_TEAMS)) {
        const [wins, podiums, poles, points, races, firstYear, lastYear] = data;
        if (firstYear >= startYear) continue;
        
        const careerYears = lastYear - firstYear + 1;
        const yearsBeforeStart = Math.min(lastYear, startYear - 1) - firstYear + 1;
        const fraction = yearsBeforeStart / careerYears;
        const isDefunct = lastYear < startYear;
        
        // v0.8.2.4: Indy/F1 Flag aus isIndyOnlyConstructor
        const teamIsIndy = isIndyOnlyConstructor(teamName);
        
        result.teams[teamName] = {
            name: teamName,
            wins: isDefunct ? wins : Math.round(wins * fraction),
            podiums: isDefunct ? podiums : Math.round(podiums * fraction),
            poles: isDefunct ? poles : Math.round(poles * fraction),
            points: isDefunct ? points : Math.round(points * fraction * 10) / 10,
            races: isDefunct ? races : Math.round(races * fraction),
            firstYear: firstYear,
            lastYear: isDefunct ? lastYear : startYear - 1,
            isDefunct: isDefunct,
            hasIndy: teamIsIndy,
            hasF1: !teamIsIndy
        };
    }
    
    for (const [year, driverId] of Object.entries(HIST_CHAMPIONS)) {
        const y = parseInt(year);
        if (y < startYear) {
            result.champions.push({
                year: y,
                driverId: driverId,
                name: HIST_NAMES[driverId] || driverId
            });

        }
    }
    result.champions.sort((a, b) => b.year - a.year);
    
    return result;
}

// Hilfsfunktion: Hole Saison-Historie für einen Fahrer
function getDriverSeasons(driverId, beforeYear) {
    const seasons = HIST_SEASONS[driverId] || [];
    if (beforeYear) {
        return seasons.filter(s => s[0] < beforeYear);
    }
    return seasons;
}

